using System.Text.Json;

namespace Sideband.Tests;

[Trait("Category", "Unit")]
public sealed class SidebandConsoleReferenceTests
{
    [Fact]
    public void ActualPrimaryVoiceConsoleHandlersAreExplicitUpstreamPlaceholders()
    {
        // Generated by executing primary cmd_voice/Command, not inferred from help text.
        using var fixture = JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Fixtures", "sideband-console.json")));
        Assert.Equal("d069122af14880e43607aed0b71add4c7806fbe0", fixture.RootElement.GetProperty("sideband_sha").GetString());
        var commands = fixture.RootElement.GetProperty("cases").EnumerateArray().ToArray();
        Assert.Equal(12, commands.Length);
        Assert.All(commands, command =>
        {
            Assert.False(command.GetProperty("handler").GetBoolean());
            Assert.Equal("Not yet implemented", command.GetProperty("result").GetString());
        });
    }
}
